
// Regression contracts: never silently repurpose an amend or submit a partial
// autogenerated message. Synthetic loopback fixture only.
#[test]
fn audit_amend_failed_message_fetch_must_not_submit_partial_message() {
    let mut fake = Fake::new();
    fake.git.changes.as_mut().unwrap()["entries"].as_array_mut().unwrap().pop();
    fake.fail.store(true, Ordering::SeqCst);
    fake.act("amend", Value::Null);
    fake.fail.store(false, Ordering::SeqCst);
    let start = fake.calls.lock().unwrap().len();
    fake.act("commit", Value::Null);
    let calls = fake.calls.lock().unwrap();
    assert!(calls[start..].iter().all(|(path, body)| {
        path != "/workspace/commit" || body.is_null() || !body.bool("amend")
    }), "failed full-message load must require retry or an explicit reviewed edit before amend");
}

#[test]
fn audit_amend_must_not_follow_changed_head_without_rearming() {
    for change_branch in [false, true] {
        let mut fake = Fake::new();
        fake.git.changes.as_mut().unwrap()["entries"].as_array_mut().unwrap().pop();
        fake.act("amend", Value::Null);
        assert_eq!(fake.git.message, "Last\n\nBody");
        let mut next = fake.git.changes();
        next["head"] = json!({"short":"bbbbbbb","summary":"A different commit"});
        if change_branch { next["branch"] = json!("other"); }
        fake.git.update(next);
        let start = fake.calls.lock().unwrap().len();
        fake.act("commit", Value::Null);
        let calls = fake.calls.lock().unwrap();
        assert!(calls[start..].iter().all(|(path, body)| {
            path != "/workspace/commit" || body.is_null() || !body.bool("amend")
        }), "amend intent was armed for another HEAD; change_branch={change_branch}");
    }
}
